import { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";

const WHATSAPP_NUMBER = "917418804656"; // ✅ 91 + number (NO + sign)

const branches = {
  "Nava India": {
    memberships: [
      ["Monthly", "₹4,000"],
      ["3 Months", "₹9,000"],
      ["6 Months", "₹12,000"],
      ["12 Months", "₹18,000"],
    ],
    addons: [
      ["Personal Training (PT)", "₹8,000"],
      ["Zumba Classes", "₹3,000"],
      ["Group Training Classes", "₹4,000"],
    ],
  },
  "RS Puram": {
    memberships: [
      ["Monthly", "₹3,000"],
      ["3 Months", "₹9,000"],
      ["6 Months", "₹12,000"],
      ["12 Months", "₹14,000"],
    ],
    addons: [["Personal Training (PT)", "₹8,000"]],
  },
  "Kovaipudur": {
    memberships: [
      ["Monthly", "₹3,000"],
      ["3 Months", "₹7,000"],
      ["6 Months", "₹9,000"],
      ["12 Months", "₹13,000"],
    ],
    addons: [["Personal Training (PT)", "₹8,000"]],
  },
};

export default function Membership() {
  const [active, setActive] = useState("Nava India");

  const getWhatsappLink = (branch) => {
    const message = `Hello, I want to join a membership at ${branch} branch (BodyZeal Fitworks). Please share details.`;
    return `https://wa.me/${WHATSAPP_NUMBER}?text=${encodeURIComponent(
      message
    )}`;
  };

  return (
    <section
      id="membership"
      className="bg-black text-white py-32 px-6 scroll-mt-28"
    >
      <div className="max-w-6xl mx-auto">
        {/* HEADING */}
        <div className="text-center max-w-3xl mx-auto mb-16">
          <h2 className="text-4xl md:text-5xl font-bold">
            Membership <span className="text-[#e9b21a]">Plans</span>
          </h2>
          <p className="mt-6 text-gray-400">
            Membership pricing varies by location. Select your nearest branch.
          </p>
        </div>

        {/* BRANCH TABS */}
        <div className="flex justify-center gap-4 mb-14 flex-wrap">
          {Object.keys(branches).map((branch) => (
            <button
              key={branch}
              onClick={() => setActive(branch)}
              className={`px-6 py-2 rounded-full border transition ${
                active === branch
                  ? "bg-[#e9b21a] border-[#e9b21a] text-black"
                  : "border-white/20 text-gray-300 hover:border-[#e9b21a]"
              }`}
            >
              {branch}
            </button>
          ))}
        </div>

        {/* PRICING */}
        <AnimatePresence mode="wait">
          <motion.div
            key={active}
            initial={{ opacity: 0, y: 30 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: 30 }}
            transition={{ duration: 0.4 }}
            className="grid md:grid-cols-2 gap-10"
          >
            {/* MEMBERSHIPS */}
            <div className="rounded-2xl border border-white/10 bg-black/60 backdrop-blur p-8">
              <h3 className="text-2xl font-semibold mb-6">
                Gym Memberships
              </h3>
              <ul className="space-y-4">
                {branches[active].memberships.map(([label, price], i) => (
                  <li
                    key={i}
                    className="flex justify-between text-gray-300 border-b border-white/10 pb-3"
                  >
                    <span>{label}</span>
                    <span className="text-white font-medium">
                      {price}
                    </span>
                  </li>
                ))}
              </ul>
            </div>

            {/* ADDONS + CTA */}
            <div className="rounded-2xl border border-white/10 bg-black/60 backdrop-blur p-8 flex flex-col">
              <h3 className="text-2xl font-semibold mb-6">
                Add-On Services
              </h3>

              <ul className="space-y-4 flex-1">
                {branches[active].addons.map(([label, price], i) => (
                  <li
                    key={i}
                    className="flex justify-between text-gray-300 border-b border-white/10 pb-3"
                  >
                    <span>{label}</span>
                    <span className="text-white font-medium">
                      {price}
                    </span>
                  </li>
                ))}
              </ul>

              {/* WHATSAPP CTA */}
              <a
  href={getWhatsappLink(active)}
  target="_blank"
  rel="noopener noreferrer"
  className="mt-10 w-full text-center px-6 py-4 rounded-full bg-[#25D366] text-black font-bold hover:scale-[1.02] transition flex items-center justify-center gap-3"
>
  💬 Join at {active} via WhatsApp
</a>

            </div>
          </motion.div>
        </AnimatePresence>
      </div>
    </section>
  );
}
